      "path": "tests/loader-composition.spec.ts",
      "content": "import { mkdtemp, rm, writeFile } from 'node:fs/promises'\nimport { tmpdir } from 'node:os'\nimport { join } from 'node:path'\nimport { pathToFileURL } from 'node:url'\nimport { afterEach, describe, expect, it } from 'vitest'\nimport { Context } from '@deepseek-ai/cordis'\nimport Include from '@deepseek-ai/cordis-plugin-include'\nimport Loader from '@deepseek-ai/cordis-plugin-loader'\nimport SessionStore, { SessionId } from '@deepseek-ai/dsh-session'\nimport { createUserMessage } from '@deepseek-ai/dsh-llm'\nimport {\n  SessionTelemetryCoordinator,\n  type SessionTelemetryRecord,\n  type SessionTelemetrySink,\n} from '@deepseek-ai/dsh-session-telemetry'\nimport * as Redactor from '../src/index.ts'\n\nconst SECRET = `sk-${'loaderfixture1234567890'}`\nlet root: string | undefined\nlet context: Context | undefined\n\nafterEach(async () => {\n  await context?.fiber.dispose()\n  context = undefined\n  if (root !== undefined) await rm(root, { recursive: true, force: true })\n  root = undefined\n})\n\ndescribe('real Loader and telemetry coordinator composition', () => {\n  it('exports a redacted copy while the canonical session event retains the secret', async () => {\n    root = await mkdtemp(join(tmpdir(), 'dsh-telemetry-redactor-'))\n    const configPath = join(root, 'cordis.yml')\n    await writeFile(configPath, [\n      \"- id: sessions\",\n      \"  name: '@deepseek-ai/dsh-session'\",\n      \"- id: telemetry-redactor\",\n      \"  name: 'dsh-telemetry-redactor'\",\n      '  config:',\n      \"    replacement: '[WIRE-REDACTED]'\",\n      \"- id: telemetry-backend\",\n      \"  name: 'fixture-telemetry-backend'\",\n      '',\n    ].join('\\n'))\n\n    const records: SessionTelemetryRecord[] = []\n    const backend: SessionTelemetrySink = {\n      emit: record => records.push(record),\n      shutdown: async () => {},\n    }\n    const fixtureBackend = {\n      name: 'fixture-telemetry-backend',\n      inject: ['sessions'],\n      apply: (ctx: Context) => void new SessionTelemetryCoordinator(ctx, backend),\n    }\n\n    const ctx = new Context()\n    context = ctx\n    ctx.baseUrl = pathToFileURL(root).href + '/'\n    await ctx.plugin(Loader)\n    ctx.loader.builtins.include = Include\n    const modules = new Map<string, unknown>([\n      ['@deepseek-ai/dsh-session', SessionStore],\n      ['dsh-telemetry-redactor', Redactor],\n      ['fixture-telemetry-backend', fixtureBackend],\n    ])\n    ctx.loader.internal = {\n      version: 'v2',\n      async import(specifier: string) {\n        if (!modules.has(specifier)) throw new Error(`unexpected Loader import: ${specifier}`)\n        return modules.get(specifier)\n      },\n    } as unknown as NonNullable<typeof ctx.loader.internal>\n    await ctx.loader.create({\n      name: 'cordis:include',\n      config: { path: pathToFileURL(configPath).href },\n    })\n    await ctx.loader.await()\n\n    const session = ctx.sessions.create(SessionId('redactor-loader'))\n    session.append('user/message', createUserMessage({\n      content: [{ type: 'text', text: `credential ${SECRET}` }],\n      source: { kind: 'user' },\n    }), { surfaceOp: 'append' })\n\n    expect(JSON.stringify(records)).not.toContain(SECRET)\n    expect(JSON.stringify(records)).toContain('[WIRE-REDACTED]')\n    expect(JSON.stringify(session.events)).toContain(SECRET)\n    expect(JSON.stringify(session.events)).not.toContain('[WIRE-REDACTED]')\n\n    let tooDeep: Record<string, unknown> = { leaf: 'safe' }\n    for (let index = 0; index < 70; index += 1) tooDeep = { child: tooDeep }\n    const count = records.length\n    const originalWarn = ctx.logger.warn\n    const warnings: string[] = []\n    ctx.logger.warn = (...args: unknown[]) => {\n      warnings.push(args.map(String).join(' '))\n    }\n    ctx.emit('session/event', session, {\n      type: 'fixture/deep',\n      seq: 1,\n      time: Date.now(),\n      data: tooDeep,\n      ignorable: true,\n    } as never)\n    expect(records).toHaveLength(count)\n    expect(warnings).toHaveLength(1)\n    expect(warnings[0]).toContain('maximum nesting depth')\n    ctx.logger.warn = originalWarn\n  })\n})\n"
    },
    {
      "path": "tests/adversarial.spec.ts",
      "content": "import { describe, expect, it } from 'vitest'\nimport { Context } from '@deepseek-ai/cordis'\nimport type { SessionTelemetryRecord } from '@deepseek-ai/dsh-session-telemetry'\nimport * as Redactor from '../src/index.ts'\n\nconst secret = (label: string) => `sk-${label}1234567890`\n\nfunction record(body: unknown): SessionTelemetryRecord {\n  return {\n    channel: 'ledger',\n    time: 1,\n    severity: 'info',\n    attributes: {\n      'session.id': 'adversarial',\n      'event.type': 'fixture/event',\n      'event.seq': 1,\n    },\n    body,\n  }\n}\n\nasync function transform(body: unknown, config: Redactor.Config = {}): Promise<SessionTelemetryRecord> {\n  const ctx = new Context()\n  await ctx.plugin(Redactor, config)\n  const input = record(body)\n  return ctx.waterfall('session-telemetry/record', input, () => input)\n}\n\ndescribe('supported secret locations', () => {\n  it('redacts key names, nested values, arrays, query parameters, headers, and error strings', async () => {\n    const keySecret = secret('objectkey')\n    const values = {\n      [keySecret]: 'key itself carried the credential',\n      nested: {\n        password: 'plain-password',\n        array: [\n          `https://example.invalid/path?access_token=${secret('query')}&page=2`,\n          `Authorization: Bearer ${secret('header')}`,\n          `request failed: api_key=${secret('error')}`,\n        ],\n      },\n    }\n\n    const output = await transform(values)\n    const wire = JSON.stringify(output)\n    for (const value of [keySecret, 'plain-password', secret('query'), secret('header'), secret('error')]) {\n      expect(wire).not.toContain(value)\n    }\n    expect(wire).toContain('[REDACTED]')\n    expect(wire).toContain('page=2')\n  })\n\n  it('preserves official and common token telemetry fields', async () => {\n    const metrics = {\n      usage: {\n        inputTokens: 11,\n        outputTokens: 7,\n        cacheReadTokens: 5,\n        cacheWriteTokens: 3,\n        reasoningTokens: 2,\n      },\n      tokenUsage: { input: 11, output: 7 },\n      tokenCount: 18,\n      totalTokens: 18,\n      contextTokens: 128_000,\n      contextTokenCount: 4_096,\n      maxTokens: 8_192,\n      prompt_tokens: 11,\n      completion_tokens: 7,\n      tokenizer: 'cl100k_base',\n    }\n\n    expect((await transform(metrics)).body).toEqual(metrics)\n  })\n})\n\ndescribe('explicit negative boundaries', () => {\n  it('does not claim to detect unlabelled opaque or encoded credentials', async () => {\n    const unsupported = {\n      opaque: 'zYxWvU9876543210',\n      sample1: 'https://example.invalid/?access%5Ftoken%3DzYxWvU9876543210',\n      sample2: 'Bearer short',\n      sample3: 'Cookie: sid=zYxWvU9876543210',\n    }\n\n    expect((await transform(unsupported)).body).toEqual(unsupported)\n  })\n\n  it('rejects a replacement that itself matches a supported secret pattern', async () => {\n    const ctx = new Context()\n    const fiber = ctx.plugin(Redactor, { replacement: secret('replacement') })\n    await expect(fiber.await()).rejects.toThrow('replacement')\n  })\n})\n\ndescribe('hostile object behavior', () => {\n  it('rejects accessors without invoking their getter', async () => {\n    let reads = 0\n    const body = Object.defineProperty({}, 'secret', {\n      enumerable: true,\n      get() {\n        reads += 1\n        return secret('getter')\n      },\n    })\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const input = record(body)\n\n    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('accessor')\n    expect(reads).toBe(0)\n\n    const array: unknown[] = []\n    Object.defineProperty(array, '0', {\n      enumerable: true,\n      get() {\n        reads += 1\n        return secret('array-getter')\n      },\n    })\n    const arrayRecord = record(array)\n    expect(() => ctx.waterfall('session-telemetry/record', arrayRecord, () => arrayRecord)).toThrow('accessor')\n    expect(reads).toBe(0)\n  })\n\n  it('rejects non-plain objects instead of silently changing their meaning', async () => {\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const input = record({ when: new Date(0) })\n\n    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('plain')\n  })\n\n  it('contains no proxy guarantee but propagates a throwing trap for coordinator containment', async () => {\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const proxy = new Proxy({}, {\n      getPrototypeOf() {\n        throw new Error('proxy trap')\n      },\n    })\n    const input = record(proxy)\n\n    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('proxy trap')\n  })\n\n  it('rejects cycles and retains linear behavior for a large shallow record', async () => {\n    const cyclic: Record<string, unknown> = {}\n    cyclic.self = cyclic\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const cyclicRecord = record(cyclic)\n    expect(() => ctx.waterfall('session-telemetry/record', cyclicRecord, () => cyclicRecord)).toThrow('cycle')\n\n    const size = 20_000\n    const shallow = Object.fromEntries(Array.from({ length: size }, (_, index) => [`metric_${index}`, index]))\n    const started = performance.now()\n    const output = await transform(shallow)\n    const elapsedMillis = performance.now() - started\n    expect(Object.keys(output.body as object)).toHaveLength(size)\n    expect(elapsedMillis).toBeLessThan(2_000)\n  })\n\n  it('rejects collisions created by redacting credential-bearing key names', async () => {\n    const first = secret('collision-a')\n    const second = secret('collision-b')\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const input = record({ [first]: 1, [second]: 2 })\n\n    expect(() => ctx.waterfall('session-telemetry/record', input, () => input)).toThrow('collision')\n  })\n})\n\ndescribe('listener composition boundary', () => {\n  it('wraps ordinary listeners mounted before the redactor', async () => {\n    const ctx = new Context()\n    ctx.on('session-telemetry/record', (_candidate, next) => ({\n      ...next(),\n      body: { apiKey: secret('ordinary-listener') },\n    }))\n    await ctx.plugin(Redactor)\n    const input = record({ safe: true })\n    expect(JSON.stringify(ctx.waterfall('session-telemetry/record', input, () => input)))\n      .not.toContain(secret('ordinary-listener'))\n  })\n\n  it('proves a more-outer prepended listener can bypass this rule', async () => {\n    const ctx = new Context()\n    await ctx.plugin(Redactor)\n    const bypass = secret('outer-bypass')\n    ctx.on('session-telemetry/record', () => record({ raw: bypass }), { prepend: true })\n    const input = record({ safe: true })\n\n    expect(JSON.stringify(ctx.waterfall('session-telemetry/record', input, () => input))).toContain(bypass)\n  })\n})\n"
    },
